    CompositeAlarm.add_member(:actions_suppressor_wait_period, Smithy::Schema::Shapes::ShapeRef.new(shape: SuppressorPeriod, location_name: 'ActionsSuppressorWaitPeriod', traits: {"smithy.api#documentation" => "<p> The maximum time in seconds that the composite alarm waits for the suppressor alarm\n            to go into the <code>ALARM</code> state. After this time, the composite alarm performs\n            its actions. </p>\n         <important>\n            <p>\n               <code>WaitPeriod</code> is required only when <code>ActionsSuppressor</code> is\n                specified. </p>\n         </important>"}))
