    GetInsightRuleReportOutput.add_member(:key_labels, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleContributorKeyLabels, location_name: 'KeyLabels', traits: {"smithy.api#documentation" => "<p>An array of the strings used as the keys for this rule. The keys are the dimensions\n            used to classify contributors. If the rule contains more than one key, then each unique\n            combination of values for the keys is counted as a unique contributor.</p>"}))
    GetInsightRuleReportOutput.add_member(:aggregation_statistic, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleAggregationStatistic, location_name: 'AggregationStatistic', traits: {"smithy.api#documentation" => "<p>Specifies whether this rule aggregates contributor data by COUNT or SUM.</p>"}))
    GetInsightRuleReportOutput.add_member(:aggregate_value, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleUnboundDouble, location_name: 'AggregateValue', traits: {"smithy.api#documentation" => "<p>The sum of the values from all individual contributors that match the rule.</p>"}))
    GetInsightRuleReportOutput.add_member(:approximate_unique_count, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleUnboundLong, location_name: 'ApproximateUniqueCount', traits: {"smithy.api#documentation" => "<p>An approximate count of the unique contributors found by this rule in this time\n            period.</p>"}))
    GetInsightRuleReportOutput.add_member(:contributors, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleContributors, location_name: 'Contributors', traits: {"smithy.api#documentation" => "<p>An array of the unique contributors found by this rule in this time period. If the\n            rule contains multiple keys, each combination of values for the keys counts as a unique\n            contributor.</p>"}))
    GetInsightRuleReportOutput.add_member(:metric_datapoints, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleMetricDatapoints, location_name: 'MetricDatapoints', traits: {"smithy.api#documentation" => "<p>A time series of metric data points that matches the time period in the rule\n            request.</p>"}))
    GetInsightRuleReportOutput.type = Types::GetInsightRuleReportOutput
    GetMetricDataInput.add_member(:metric_data_queries, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricDataQueries, location_name: 'MetricDataQueries', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The metric queries to be returned. A single <code>GetMetricData</code> call can\n            include as many as 500 <code>MetricDataQuery</code> structures. Each of these structures\n            can specify either a metric to retrieve, a Metrics Insights query, or a math expression\n            to perform on retrieved data. </p>", "smithy.api#required" => {}}))
    GetMetricDataInput.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'StartTime', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The time stamp indicating the earliest data to be returned.</p>\n         <p>The value specified is inclusive; results include data points with the specified\n            time stamp. </p>\n         <p>CloudWatch rounds the specified time stamp as follows:</p>\n         <ul>\n            <li>\n               <p>Start time less than 15 days ago - Round down to the nearest whole minute.\n                    For example, 12:32:34 is rounded down to 12:32:00.</p>\n            </li>\n            <li>\n               <p>Start time between 15 and 63 days ago - Round down to the nearest 5-minute\n                    clock interval. For example, 12:32:34 is rounded down to 12:30:00.</p>\n            </li>\n            <li>\n               <p>Start time greater than 63 days ago - Round down to the nearest 1-hour\n                    clock interval. For example, 12:32:34 is rounded down to 12:00:00.</p>\n            </li>\n         </ul>\n         <p>If you set <code>Period</code> to 5, 10, 20, or 30, the start time of your request is\n            rounded down to the nearest time that corresponds to even 5-, 10-, 20-, or 30-second\n            divisions of a minute. For example, if you make a query at (HH:mm:ss) 01:05:23 for the\n            previous 10-second period, the start time of your request is rounded down and you\n            receive data from 01:05:10 to 01:05:20. If you make a query at 15:07:17 for the previous\n            5 minutes of data, using a period of 5 seconds, you receive data timestamped between\n            15:02:15 and 15:07:15. </p>\n         <p>For better performance, specify <code>StartTime</code> and <code>EndTime</code> values\n            that align with the value of the metric's <code>Period</code> and sync up with the\n            beginning and end of an hour. For example, if the <code>Period</code> of a metric is 5\n            minutes, specifying 12:05 or 12:30 as <code>StartTime</code> can get a faster response\n            from CloudWatch than setting 12:07 or 12:29 as the <code>StartTime</code>.</p>", "smithy.api#required" => {}}))
    GetMetricDataInput.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'EndTime', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The time stamp indicating the latest data to be returned.</p>\n         <p>The value specified is exclusive; results include data points up to the specified\n            time stamp.</p>\n         <p>For better performance, specify <code>StartTime</code> and <code>EndTime</code> values\n            that align with the value of the metric's <code>Period</code> and sync up with the\n            beginning and end of an hour. For example, if the <code>Period</code> of a metric is 5\n            minutes, specifying 12:05 or 12:30 as <code>EndTime</code> can get a faster response\n            from CloudWatch than setting 12:07 or 12:29 as the <code>EndTime</code>.</p>", "smithy.api#required" => {}}))
    GetMetricDataInput.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NextToken, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>Include this value, if it was returned by the previous <code>GetMetricData</code>\n            operation, to get the next set of data points.</p>"}))
    GetMetricDataInput.add_member(:scan_by, Smithy::Schema::Shapes::ShapeRef.new(shape: ScanBy, location_name: 'ScanBy', traits: {"smithy.api#documentation" => "<p>The order in which data points should be returned. <code>TimestampDescending</code>\n            returns the newest data first and paginates when the <code>MaxDatapoints</code> limit is\n            reached. <code>TimestampAscending</code> returns the oldest data first and paginates\n            when the <code>MaxDatapoints</code> limit is reached.</p>\n         <p>If you omit this parameter, the default of <code>TimestampDescending</code> is\n            used.</p>"}))
    GetMetricDataInput.add_member(:max_datapoints, Smithy::Schema::Shapes::ShapeRef.new(shape: GetMetricDataMaxDatapoints, location_name: 'MaxDatapoints', traits: {"smithy.api#documentation" => "<p>The maximum number of data points the request should return before paginating. If you\n            omit this, the default of 100,800 is used.</p>"}))
    GetMetricDataInput.add_member(:label_options, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelOptions, location_name: 'LabelOptions', traits: {"smithy.api#documentation" => "<p>This structure includes the <code>Timezone</code> parameter, which you can use to\n            specify your time zone so that the labels of returned data display the correct time for\n            your time zone. </p>"}))
    GetMetricDataInput.type = Types::GetMetricDataInput
    GetMetricDataOutput.add_member(:metric_data_results, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricDataResults, location_name: 'MetricDataResults', traits: {"smithy.api#documentation" => "<p>The metrics that are returned, including the metric name, namespace, and\n            dimensions.</p>"}))
    GetMetricDataOutput.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NextToken, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>A token that marks the next batch of returned results.</p>"}))
    GetMetricDataOutput.add_member(:messages, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricDataResultMessages, location_name: 'Messages', traits: {"smithy.api#documentation" => "<p>Contains a message about this <code>GetMetricData</code> operation, if the operation\n            results in such a message. An example of a message that might be returned is\n                <code>Maximum number of allowed metrics exceeded</code>. If there is a message, as\n            much of the operation as possible is still executed.</p>\n         <p>A message appears here only if it is related to the global <code>GetMetricData</code>\n            operation. Any message about a specific metric returned by the operation appears in the\n                <code>MetricDataResult</code> object returned for that metric.</p>"}))
    GetMetricDataOutput.type = Types::GetMetricDataOutput
    GetMetricStatisticsInput.add_member(:namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: Namespace, location_name: 'Namespace', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The namespace of the metric, with or without spaces.</p>", "smithy.api#required" => {}}))
    GetMetricStatisticsInput.add_member(:metric_name, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricName, location_name: 'MetricName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the metric, with or without spaces.</p>", "smithy.api#required" => {}}))
    GetMetricStatisticsInput.add_member(:dimensions, Smithy::Schema::Shapes::ShapeRef.new(shape: Dimensions, location_name: 'Dimensions', traits: {"smithy.api#documentation" => "<p>The dimensions. If the metric contains multiple dimensions, you must include a\n            value for each dimension. CloudWatch treats each unique combination of dimensions as a\n            separate metric. If a specific combination of dimensions was not published, you can't\n            retrieve statistics for it. You must specify the same dimensions that were used when the\n            metrics were created. For an example, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/cloudwatch_concepts.html#dimension-combinations\">Dimension Combinations</a> in the <i>Amazon CloudWatch User\n            Guide</i>. For more information about specifying dimensions, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/publishingMetrics.html\">Publishing Metrics</a> in the <i>Amazon CloudWatch User\n            Guide</i>.</p>"}))
    GetMetricStatisticsInput.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'StartTime', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The time stamp that determines the first data point to return. Start times are\n            evaluated relative to the time that CloudWatch receives the request.</p>\n         <p>The value specified is inclusive; results include data points with the specified\n            time stamp. In a raw HTTP query, the time stamp must be in ISO 8601 UTC format (for\n            example, 2016-10-03T23:00:00Z).</p>\n         <p>CloudWatch rounds the specified time stamp as follows:</p>\n         <ul>\n            <li>\n               <p>Start time less than 15 days ago - Round down to the nearest whole minute.\n                    For example, 12:32:34 is rounded down to 12:32:00.</p>\n            </li>\n            <li>\n               <p>Start time between 15 and 63 days ago - Round down to the nearest 5-minute\n                    clock interval. For example, 12:32:34 is rounded down to 12:30:00.</p>\n            </li>\n            <li>\n               <p>Start time greater than 63 days ago - Round down to the nearest 1-hour\n                    clock interval. For example, 12:32:34 is rounded down to 12:00:00.</p>\n            </li>\n         </ul>\n         <p>If you set <code>Period</code> to 5, 10, 20, or 30, the start time of your request is\n            rounded down to the nearest time that corresponds to even 5-, 10-, 20-, or 30-second\n            divisions of a minute. For example, if you make a query at (HH:mm:ss) 01:05:23 for the\n            previous 10-second period, the start time of your request is rounded down and you\n            receive data from 01:05:10 to 01:05:20. If you make a query at 15:07:17 for the previous\n            5 minutes of data, using a period of 5 seconds, you receive data timestamped between\n            15:02:15 and 15:07:15. </p>", "smithy.api#required" => {}}))
    GetMetricStatisticsInput.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'EndTime', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The time stamp that determines the last data point to return.</p>\n         <p>The value specified is exclusive; results include data points up to the specified\n            time stamp. In a raw HTTP query, the time stamp must be in ISO 8601 UTC format (for\n            example, 2016-10-10T23:00:00Z).</p>", "smithy.api#required" => {}}))
    GetMetricStatisticsInput.add_member(:period, Smithy::Schema::Shapes::ShapeRef.new(shape: Period, location_name: 'Period', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The granularity, in seconds, of the returned data points. For metrics with regular\n            resolution, a period can be as short as one minute (60 seconds) and must be a multiple\n            of 60. For high-resolution metrics that are collected at intervals of less than one\n            minute, the period can be 1, 5, 10, 20, 30, 60, or any multiple of 60. High-resolution\n            metrics are those metrics stored by a <code>PutMetricData</code> call that includes a\n            <code>StorageResolution</code> of 1 second.</p>\n         <p>If the <code>StartTime</code> parameter specifies a time stamp that is greater than\n            3 hours ago, you must specify the period as follows or no data points in that time range\n            is returned:</p>\n         <ul>\n            <li>\n               <p>Start time between 3 hours and 15 days ago - Use a multiple of 60 seconds\n                    (1 minute).</p>\n            </li>\n            <li>\n               <p>Start time between 15 and 63 days ago - Use a multiple of 300 seconds (5\n                    minutes).</p>\n            </li>\n            <li>\n               <p>Start time greater than 63 days ago - Use a multiple of 3600 seconds (1\n                    hour).</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    GetMetricStatisticsInput.add_member(:statistics, Smithy::Schema::Shapes::ShapeRef.new(shape: Statistics, location_name: 'Statistics', traits: {"smithy.api#documentation" => "<p>The metric statistics, other than percentile. For percentile statistics, use\n            <code>ExtendedStatistics</code>. When calling <code>GetMetricStatistics</code>, you\n            must specify either <code>Statistics</code> or <code>ExtendedStatistics</code>, but not\n            both.</p>"}))
    GetMetricStatisticsInput.add_member(:extended_statistics, Smithy::Schema::Shapes::ShapeRef.new(shape: ExtendedStatistics, location_name: 'ExtendedStatistics', traits: {"smithy.api#documentation" => "<p>The percentile statistics. Specify values between p0.0 and p100. When calling\n            <code>GetMetricStatistics</code>, you must specify either <code>Statistics</code> or\n            <code>ExtendedStatistics</code>, but not both. Percentile statistics are not\n            available for metrics when any of the metric values are negative numbers.</p>"}))
    GetMetricStatisticsInput.add_member(:unit, Smithy::Schema::Shapes::ShapeRef.new(shape: StandardUnit, location_name: 'Unit', traits: {"smithy.api#documentation" => "<p>The unit for a given metric. If you omit <code>Unit</code>, all data that was\n            collected with any unit is returned, along with the corresponding units that were\n            specified when the data was reported to CloudWatch. If you specify a unit, the operation\n            returns only data that was collected with that unit specified. If you specify a unit\n            that does not match the data collected, the results of the operation are null.\n            CloudWatch does not perform unit conversions.</p>"}))
    GetMetricStatisticsInput.type = Types::GetMetricStatisticsInput
    GetMetricStatisticsOutput.add_member(:label, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricLabel, location_name: 'Label', traits: {"smithy.api#documentation" => "<p>A label for the specified metric.</p>"}))
    GetMetricStatisticsOutput.add_member(:datapoints, Smithy::Schema::Shapes::ShapeRef.new(shape: Datapoints, location_name: 'Datapoints', traits: {"smithy.api#documentation" => "<p>The data points for the specified metric.</p>"}))
