    GetMetricStreamOutput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStreamName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the metric stream.</p>"}))
    GetMetricStreamOutput.add_member(:include_filters, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStreamFilters, location_name: 'IncludeFilters', traits: {"smithy.api#documentation" => "<p>If this array of metric namespaces is present, then these namespaces are the only\n            metric namespaces that are streamed by this metric stream.</p>"}))
    GetMetricStreamOutput.add_member(:exclude_filters, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStreamFilters, location_name: 'ExcludeFilters', traits: {"smithy.api#documentation" => "<p>If this array of metric namespaces is present, then these namespaces are the only\n            metric namespaces that are not streamed by this metric stream. In this case, all other\n            metric namespaces in the account are streamed by this metric stream.</p>"}))
    GetMetricStreamOutput.add_member(:firehose_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: AmazonResourceName, location_name: 'FirehoseArn', traits: {"smithy.api#documentation" => "<p>The ARN of the Amazon Kinesis Data Firehose delivery stream that is used by this\n            metric stream.</p>"}))
    GetMetricStreamOutput.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: AmazonResourceName, location_name: 'RoleArn', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role that is used by this metric stream.</p>"}))
    GetMetricStreamOutput.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStreamState, location_name: 'State', traits: {"smithy.api#documentation" => "<p>The state of the metric stream. The possible values are <code>running</code> and\n            <code>stopped</code>.</p>"}))
    GetMetricStreamOutput.add_member(:creation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationDate', traits: {"smithy.api#documentation" => "<p>The date that the metric stream was created.</p>"}))
    GetMetricStreamOutput.add_member(:last_update_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'LastUpdateDate', traits: {"smithy.api#documentation" => "<p>The date of the most recent update to the metric stream's configuration.</p>"}))
    GetMetricStreamOutput.add_member(:output_format, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStreamOutputFormat, location_name: 'OutputFormat', traits: {"smithy.api#documentation" => "<p>The output format for the stream. Valid values are <code>json</code>,\n            <code>opentelemetry1.0</code>, and <code>opentelemetry0.7</code>. For more\n            information about metric stream output formats, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/CloudWatch-metric-streams-formats.html\">Metric streams output formats</a>.</p>"}))
    GetMetricStreamOutput.add_member(:statistics_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStreamStatisticsConfigurations, location_name: 'StatisticsConfigurations', traits: {"smithy.api#documentation" => "<p>Each entry in this array displays information about one or more metrics that include\n            additional statistics in the metric stream. For more information about the additional\n            statistics, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/Statistics-definitions.html.html\">\n                CloudWatch statistics definitions</a>. </p>"}))
    GetMetricStreamOutput.add_member(:include_linked_accounts_metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: IncludeLinkedAccountsMetrics, location_name: 'IncludeLinkedAccountsMetrics', traits: {"smithy.api#documentation" => "<p>If this is <code>true</code> and this metric stream is in a monitoring account, then\n            the stream includes metrics from source accounts that the monitoring account is linked\n            to.</p>"}))
    GetMetricStreamOutput.type = Types::GetMetricStreamOutput
    GetMetricWidgetImageInput.add_member(:metric_widget, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricWidget, location_name: 'MetricWidget', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A JSON string that defines the bitmap graph to be retrieved. The string includes\n            the metrics to include in the graph, statistics, annotations, title, axis limits, and so\n            on. You can include only one <code>MetricWidget</code> parameter in each\n            <code>GetMetricWidgetImage</code> call.</p>\n         <p>For more information about the syntax of <code>MetricWidget</code> see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/APIReference/CloudWatch-Metric-Widget-Structure.html\">GetMetricWidgetImage: Metric Widget Structure and Syntax</a>.</p>\n         <p>If any metric on the graph could not load all the requested data points, an orange\n            triangle with an exclamation point appears next to the graph legend.</p>", "smithy.api#required" => {}}))
    GetMetricWidgetImageInput.add_member(:output_format, Smithy::Schema::Shapes::ShapeRef.new(shape: OutputFormat, location_name: 'OutputFormat', traits: {"smithy.api#documentation" => "<p>The format of the resulting image. Only PNG images are supported.</p>\n         <p>The default is <code>png</code>. If you specify <code>png</code>, the API returns\n            an HTTP response with the content-type set to <code>text/xml</code>. The image data is\n            in a <code>MetricWidgetImage</code> field. For example:</p>\n         <p>\n            <code> <GetMetricWidgetImageResponse xmlns=<URLstring>></code>\n         </p>\n         <p>\n            <code> <GetMetricWidgetImageResult></code>\n         </p>\n         <p>\n            <code> <MetricWidgetImage></code>\n         </p>\n         <p>\n            <code> iVBORw0KGgoAAAANSUhEUgAAAlgAAAGQEAYAAAAip...</code>\n         </p>\n         <p>\n            <code> </MetricWidgetImage></code>\n         </p>\n         <p>\n            <code> </GetMetricWidgetImageResult></code>\n         </p>\n         <p>\n            <code> <ResponseMetadata></code>\n         </p>\n         <p>\n            <code>\n            <RequestId>6f0d4192-4d42-11e8-82c1-f539a07e0e3b</RequestId></code>\n         </p>\n         <p>\n            <code> </ResponseMetadata></code>\n         </p>\n         <p>\n            <code></GetMetricWidgetImageResponse></code>\n         </p>\n         <p>The <code>image/png</code> setting is intended only for custom HTTP requests. For\n            most use cases, and all actions using an Amazon Web Services SDK, you should use\n            <code>png</code>. If you specify <code>image/png</code>, the HTTP response has a\n            content-type set to <code>image/png</code>, and the body of the response is a PNG \n            image.</p>"}))
    GetMetricWidgetImageInput.type = Types::GetMetricWidgetImageInput
    GetMetricWidgetImageOutput.add_member(:metric_widget_image, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricWidgetImage, location_name: 'MetricWidgetImage', traits: {"smithy.api#documentation" => "<p>The image of the graph, in the output format specified. The output is\n            base64-encoded.</p>"}))
    GetMetricWidgetImageOutput.type = Types::GetMetricWidgetImageOutput
