    InsightRule.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleName, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the rule.</p>", "smithy.api#required" => {}}))
    InsightRule.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleState, location_name: 'State', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Indicates whether the rule is enabled or disabled.</p>", "smithy.api#required" => {}}))
    InsightRule.add_member(:schema, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleSchema, location_name: 'Schema', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>For rules that you create, this is always <code>{\"Name\": \"CloudWatchLogRule\",\n            \"Version\": 1}</code>. For managed rules, this is <code>{\"Name\": \"ServiceLogRule\",\n                \"Version\": 1}</code>\n         </p>", "smithy.api#required" => {}}))
    InsightRule.add_member(:definition, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleDefinition, location_name: 'Definition', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The definition of the rule, as a JSON object. The definition contains the keywords\n            used to define contributors, the value to aggregate on if this rule returns a sum\n            instead of a count, and the filters. For details on the valid syntax, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/ContributorInsights-RuleSyntax.html\">Contributor Insights Rule Syntax</a>.</p>", "smithy.api#required" => {}}))
    InsightRule.add_member(:managed_rule, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleIsManaged, location_name: 'ManagedRule', traits: {"smithy.api#documentation" => "<p> An optional built-in rule that Amazon Web Services manages. </p>"}))
    InsightRule.add_member(:apply_on_transformed_logs, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleOnTransformedLogs, location_name: 'ApplyOnTransformedLogs', traits: {"smithy.api#documentation" => "<p>Displays whether the rule is evaluated on the transformed versions of logs, for log groups\n            that have <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/logs/CloudWatch-Logs-Transformation.html\">Log transformation</a> enabled. If this is <code>false</code>, log events are evaluated before they are transformed.</p>"}))
    InsightRule.type = Types::InsightRule
    InsightRuleContributor.add_member(:keys, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleContributorKeys, location_name: 'Keys', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>One of the log entry field keywords that is used to define contributors for this\n            rule.</p>", "smithy.api#required" => {}}))
    InsightRuleContributor.add_member(:approximate_aggregate_value, Smithy::Schema::Shapes::ShapeRef.new(shape: InsightRuleUnboundDouble, location_name: 'ApproximateAggregateValue', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>An approximation of the aggregate value that comes from this contributor.</p>", "smithy.api#required" => {}}))
