    MetricAlarm.add_member(:comparison_operator, Smithy::Schema::Shapes::ShapeRef.new(shape: ComparisonOperator, location_name: 'ComparisonOperator', traits: {"smithy.api#documentation" => "<p>The arithmetic operation to use when comparing the specified statistic and\n            threshold. The specified statistic value is used as the first operand.</p>"}))
    MetricAlarm.add_member(:treat_missing_data, Smithy::Schema::Shapes::ShapeRef.new(shape: TreatMissingData, location_name: 'TreatMissingData', traits: {"smithy.api#documentation" => "<p>Sets how this alarm is to handle missing data points. The valid values are\n            <code>breaching</code>, <code>notBreaching</code>, <code>ignore</code>, and\n            <code>missing</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/AlarmThatSendsEmail.html#alarms-and-missing-data\">Configuring how CloudWatch alarms treat missing data</a>.</p>\n         <p>If this parameter is omitted, the default behavior of <code>missing</code> is\n            used.</p>"}))
    MetricAlarm.add_member(:evaluate_low_sample_count_percentile, Smithy::Schema::Shapes::ShapeRef.new(shape: EvaluateLowSampleCountPercentile, location_name: 'EvaluateLowSampleCountPercentile', traits: {"smithy.api#documentation" => "<p>Used only for alarms based on percentiles. If <code>ignore</code>, the alarm state\n            does not change during periods with too few data points to be statistically significant.\n            If <code>evaluate</code> or this parameter is not used, the alarm is always evaluated\n            and possibly changes state no matter how many data points are available.</p>"}))
    MetricAlarm.add_member(:metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricDataQueries, location_name: 'Metrics', traits: {"smithy.api#documentation" => "<p>An array of MetricDataQuery structures, used in an alarm based on a metric math\n            expression. Each structure either retrieves a metric or performs a math expression. One\n            item in the Metrics array is the math expression that the alarm watches. This expression\n            by designated by having <code>ReturnData</code> set to true.</p>"}))
    MetricAlarm.add_member(:threshold_metric_id, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricId, location_name: 'ThresholdMetricId', traits: {"smithy.api#documentation" => "<p>In an alarm based on an anomaly detection model, this is the ID of the\n            <code>ANOMALY_DETECTION_BAND</code> function used as the threshold for the\n            alarm.</p>"}))
    MetricAlarm.add_member(:evaluation_state, Smithy::Schema::Shapes::ShapeRef.new(shape: EvaluationState, location_name: 'EvaluationState', traits: {"smithy.api#documentation" => "<p>If the value of this field is <code>PARTIAL_DATA</code>, the alarm is being evaluated\n            based on only partial data. This happens if the query used for the alarm returns more\n            than 10,000 metrics. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/Create_Metrics_Insights_Alarm.html\">Create\n                alarms on Metrics Insights queries</a>.</p>"}))
    MetricAlarm.add_member(:state_transitioned_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'StateTransitionedTimestamp', traits: {"smithy.api#documentation" => "<p>The date and time that the alarm's <code>StateValue</code> most recently\n            changed.</p>"}))
    MetricAlarm.type = Types::MetricAlarm
    MetricAlarms.member = Smithy::Schema::Shapes::ShapeRef.new(shape: MetricAlarm)
    MetricCharacteristics.add_member(:periodic_spikes, Smithy::Schema::Shapes::ShapeRef.new(shape: PeriodicSpikes, location_name: 'PeriodicSpikes', traits: {"smithy.api#documentation" => "<p>Set this parameter to <code>true</code> if values for this metric consistently include\n            spikes that should not be considered to be anomalies. With this set to\n            <code>true</code>, CloudWatch will expect to see spikes that occurred\n            consistently during the model training period, and won't flag future similar spikes as\n            anomalies.</p>"}))
    MetricCharacteristics.type = Types::MetricCharacteristics
