    MetricStreamEntry.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStreamState, location_name: 'State', traits: {"smithy.api#documentation" => "<p>The current state of this stream. Valid values are <code>running</code> and\n            <code>stopped</code>.</p>"}))
    MetricStreamEntry.add_member(:output_format, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStreamOutputFormat, location_name: 'OutputFormat', traits: {"smithy.api#documentation" => "<p>The output format of this metric stream. Valid values are <code>json</code>,\n            <code>opentelemetry1.0</code>, and <code>opentelemetry0.7</code>.</p>"}))
