    MetricStreamStatisticsConfiguration.add_member(:include_metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStreamStatisticsIncludeMetrics, location_name: 'IncludeMetrics', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>An array of metric name and namespace pairs that stream the additional statistics\n            listed in the value of the <code>AdditionalStatistics</code> parameter. There can be as\n            many as 100 pairs in the array.</p>\n         <p>All metrics that match the combination of metric name and namespace will be streamed\n            with the additional statistics, no matter their dimensions.</p>", "smithy.api#required" => {}}))
    MetricStreamStatisticsConfiguration.add_member(:additional_statistics, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStreamStatisticsAdditionalStatistics, location_name: 'AdditionalStatistics', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The list of additional statistics that are to be streamed for the metrics listed in\n            the <code>IncludeMetrics</code> array in this structure. This list can include as many\n            as 20 statistics.</p>\n         <p>If the <code>OutputFormat</code> for the stream is <code>opentelemetry1.0</code> or\n            <code>opentelemetry0.7</code>, the only valid values are\n            <code>p<i>??</i>\n            </code> percentile statistics such as\n            <code>p90</code>, <code>p99</code> and so on.</p>\n         <p>If the <code>OutputFormat</code> for the stream is <code>json</code>, the valid values\n            include the abbreviations for all of the statistics listed in <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/Statistics-definitions.html.html\">\n                CloudWatch statistics definitions</a>. For example, this includes\n            <code>tm98, </code>\n            <code>wm90</code>, <code>PR(:300)</code>, and so on.</p>", "smithy.api#required" => {}}))
