    PutAnomalyDetectorInput.add_member(:namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: Namespace, location_name: 'Namespace', traits: {"smithy.api#deprecated" => {"message" => "Use SingleMetricAnomalyDetector."}, "smithy.api#documentation" => "<p>The namespace of the metric to create the anomaly detection model for.</p>"}))
    PutAnomalyDetectorInput.add_member(:metric_name, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricName, location_name: 'MetricName', traits: {"smithy.api#deprecated" => {"message" => "Use SingleMetricAnomalyDetector."}, "smithy.api#documentation" => "<p>The name of the metric to create the anomaly detection model for.</p>"}))
    PutAnomalyDetectorInput.add_member(:dimensions, Smithy::Schema::Shapes::ShapeRef.new(shape: Dimensions, location_name: 'Dimensions', traits: {"smithy.api#deprecated" => {"message" => "Use SingleMetricAnomalyDetector."}, "smithy.api#documentation" => "<p>The metric dimensions to create the anomaly detection model for.</p>"}))
    PutAnomalyDetectorInput.add_member(:stat, Smithy::Schema::Shapes::ShapeRef.new(shape: AnomalyDetectorMetricStat, location_name: 'Stat', traits: {"smithy.api#deprecated" => {"message" => "Use SingleMetricAnomalyDetector."}, "smithy.api#documentation" => "<p>The statistic to use for the metric and the anomaly detection model.</p>"}))
    PutAnomalyDetectorInput.add_member(:configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AnomalyDetectorConfiguration, location_name: 'Configuration', traits: {"smithy.api#documentation" => "<p>The configuration specifies details about how the anomaly detection model is to be\n            trained, including time ranges to exclude when training and updating the model. You can\n            specify as many as 10 time ranges.</p>\n         <p>The configuration can also include the time zone to use for the metric.</p>"}))
    PutAnomalyDetectorInput.add_member(:metric_characteristics, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricCharacteristics, location_name: 'MetricCharacteristics', traits: {"smithy.api#documentation" => "<p>Use this object to include parameters to provide information about your metric to\n            CloudWatch to help it build more accurate anomaly detection models.\n            Currently, it includes the <code>PeriodicSpikes</code> parameter.</p>"}))
    PutAnomalyDetectorInput.add_member(:single_metric_anomaly_detector, Smithy::Schema::Shapes::ShapeRef.new(shape: SingleMetricAnomalyDetector, location_name: 'SingleMetricAnomalyDetector', traits: {"smithy.api#documentation" => "<p>A single metric anomaly detector to be created.</p>\n         <p>When using <code>SingleMetricAnomalyDetector</code>, you cannot include the following\n            parameters in the same operation:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Dimensions</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>MetricName</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Namespace</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Stat</code>\n               </p>\n            </li>\n            <li>\n               <p>the <code>MetricMathAnomalyDetector</code> parameters of\n                    <code>PutAnomalyDetectorInput</code>\n               </p>\n            </li>\n         </ul>\n         <p>Instead, specify the single metric anomaly detector attributes as part of the property\n            <code>SingleMetricAnomalyDetector</code>.</p>"}))
    PutAnomalyDetectorInput.add_member(:metric_math_anomaly_detector, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricMathAnomalyDetector, location_name: 'MetricMathAnomalyDetector', traits: {"smithy.api#documentation" => "<p>The metric math anomaly detector to be created.</p>\n         <p>When using <code>MetricMathAnomalyDetector</code>, you cannot include the following\n            parameters in the same operation:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Dimensions</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>MetricName</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Namespace</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Stat</code>\n               </p>\n            </li>\n            <li>\n               <p>the <code>SingleMetricAnomalyDetector</code> parameters of\n                    <code>PutAnomalyDetectorInput</code>\n               </p>\n            </li>\n         </ul>\n         <p>Instead, specify the metric math anomaly detector attributes as part of the property\n            <code>MetricMathAnomalyDetector</code>.</p>"}))
